// src/database/drizzle/sqlite-core/effect/count.ts
import { applyEffectWrapper } from "drizzle-orm/effect-core/query-effect";
import { entityKind } from "drizzle-orm/entity";
import { SQL, sql } from "drizzle-orm/sql/sql";
function buildSQLiteEmbeddedCount(source, filters) {
  return sql`(select count(*) from ${source}${sql.raw(" where ").if(filters)}${filters})`;
}
function buildSQLiteCount(source, filters) {
  return sql`select count(*) from ${source}${sql.raw(" where ").if(filters)}${filters}`;
}

class SQLiteEffectCountBuilder2 extends SQL {
  static [entityKind] = "SQLiteEffectCountBuilder";
  sql;
  session;
  constructor(params) {
    super(buildSQLiteEmbeddedCount(params.source, params.filters).queryChunks);
    this.session = params.session;
    this.sql = buildSQLiteCount(params.source, params.filters);
  }
  execute(placeholderValues) {
    return this.session.prepareQuery(this.session.dialect.sqlToQuery(this.sql), undefined, "all", (rows) => {
      const v = rows[0]?.[0];
      if (typeof v === "number")
        return v;
      return v ? Number(v) : 0;
    }).execute(placeholderValues);
  }
}
applyEffectWrapper(SQLiteEffectCountBuilder2);

export { SQLiteEffectCountBuilder2 };
